//! OpenAI-compatible chat completions, which Ollama also serves: `POST <base>/chat/completions`
//! with `Authorization: Bearer <key>` (OpenAI's OpenAPI description, `securitySchemes`
//! `ApiKeyAuth`: `type: http`, `scheme: bearer`). Tools are `{"type": "function", "function":
//! {name, description, parameters}}` (`ChatCompletionTool`, `FunctionObject`); a call comes
//! back in `choices[0].message.tool_calls` with `function.arguments` "as generated by the
//! model in JSON format" (`ChatCompletionMessageToolCall`), and its result goes back as a
//! message of role `tool` with its `tool_call_id` (`ChatCompletionRequestToolMessage`).
//! Fetched from `openai/openai-openapi`, `openapi.yaml`, on 2026-11-10.

use serde_json::{Value, json};

use qs_agent::{Message, ModelError, Reply, ToolCall, ToolSpec};

use crate::{Header, ProviderConfig, Secret, command_of, result_text, tool_name};

impl ProviderConfig {
    /// The request for the next reply: its URL, headers and body.
    pub(crate) fn openai_request(
        &self,
        key: Option<&Secret>,
        system: &str,
        tools: &[ToolSpec],
        transcript: &[Message],
        sent: &[Value],
    ) -> (String, Vec<Header>, Value) {
        let mut headers = Vec::new();
        if let Some(key) = key {
            headers.push(Header::Secret(
                "authorization",
                crate::Secret::new(format!("Bearer {}", key.expose())),
            ));
        }
        let mut messages = vec![json!({ "role": "system", "content": system })];
        let mut replies = sent.iter();
        for message in transcript {
            messages.push(match message {
                Message::User { text } => json!({ "role": "user", "content": text }),
                // `ChatCompletionRequestMessageContentPartImage`: `type` `image_url`, whose
                // `url` is "Either a URL of the image or the base64 encoded image data", sent as
                // the data URL its example writes, `"url": "data:image/jpeg;base64,abcdefg..."`.
                Message::Image { media_type, data } => json!({
                    "role": "user",
                    "content": [{
                        "type": "image_url",
                        "image_url": { "url": format!("data:{media_type};base64,{data}") },
                    }],
                }),
                Message::Assistant { text, calls } => match replies.next() {
                    Some(raw) if raw.is_object() => raw.clone(),
                    _ => assistant(text, calls),
                },
                Message::Tool {
                    call_id, content, ..
                } => json!({
                    "role": "tool",
                    "tool_call_id": call_id,
                    "content": result_text(content),
                }),
            });
        }
        let mut body = json!({ "model": self.model, "messages": messages });
        if !tools.is_empty()
            && let Some(object) = body.as_object_mut()
        {
            let tools: Vec<Value> = tools
                .iter()
                .map(|tool| {
                    json!({
                        "type": "function",
                        "function": {
                            "name": tool_name(&tool.name),
                            "description": tool.description,
                            "parameters": tool.input_schema,
                        },
                    })
                })
                .collect();
            object.insert("tools".to_owned(), Value::Array(tools));
        }
        let url = format!("{}/chat/completions", self.base_url());
        (url, headers, body)
    }
}

/// An assistant message built from the transcript, for one the provider did not send.
fn assistant(text: &str, calls: &[ToolCall]) -> Value {
    let mut message = json!({ "role": "assistant", "content": text });
    if !calls.is_empty()
        && let Some(object) = message.as_object_mut()
    {
        let calls: Vec<Value> = calls
            .iter()
            .map(|call| {
                json!({
                    "id": call.id,
                    "type": "function",
                    "function": {
                        "name": tool_name(&call.name),
                        "arguments": call.arguments.to_string(),
                    },
                })
            })
            .collect();
        object.insert("tool_calls".to_owned(), Value::Array(calls));
    }
    message
}

/// The reply in `answer`, and the message to send back for it.
pub(crate) fn reply(answer: &Value, tools: &[ToolSpec]) -> Result<(Reply, Value), ModelError> {
    let choice = answer
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .ok_or_else(|| ModelError::Malformed(format!("the answer has no choices: {answer}")))?;
    let finish = choice.get("finish_reason").and_then(Value::as_str);
    if finish == Some("content_filter") {
        return Err(ModelError::Filtered);
    }
    let message = choice
        .get("message")
        .ok_or_else(|| ModelError::Malformed(format!("the choice has no message: {choice}")))?;
    let text = message
        .get("content")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let calls: Vec<ToolCall> = message
        .get("tool_calls")
        .and_then(Value::as_array)
        .map(|calls| calls.iter().map(|call| tool_call(call, tools)).collect())
        .unwrap_or_default();
    let raw = message.clone();
    if !calls.is_empty() {
        return Ok((Reply::Calls { text, calls }, raw));
    }
    if finish == Some("length") {
        return Err(ModelError::CutOff);
    }
    Ok((Reply::Finish { summary: text }, raw))
}

/// One call. Arguments that are not JSON are passed on as the text the model wrote, which the
/// command then refuses with an error the model reads.
fn tool_call(call: &Value, tools: &[ToolSpec]) -> ToolCall {
    let id = call.get("id").and_then(Value::as_str).unwrap_or_default();
    let function = call.get("function");
    let name = function
        .and_then(|f| f.get("name"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    let arguments = match function.and_then(|f| f.get("arguments")) {
        Some(Value::String(text)) => {
            serde_json::from_str(text).unwrap_or_else(|_| Value::String(text.clone()))
        }
        Some(other) => other.clone(),
        None => json!({}),
    };
    ToolCall {
        id: id.to_owned(),
        name: command_of(name, tools),
        arguments,
    }
}
